//! 📐️ Editable rectangular native guides map to four real IDML ruler guides with owned grouping labels.
use super::*;
fn labels(page:&str,index:usize,edge:&str)->XmlNode{element("Properties",Vec::new(),vec![element("Label",Vec::new(),vec![element("KeyValuePair",vec![("Key","semio:guide-page".into()),("Value",page.into())],Vec::new()),element("KeyValuePair",vec![("Key","semio:guide-index".into()),("Value",index.to_string())],Vec::new()),element("KeyValuePair",vec![("Key","semio:guide-edge".into()),("Value",edge.into())],Vec::new())])])}
